#include <string>

class Solution {
public:
    std::string decodeCiphertext(std::string encodedText, int rows) {
        if (encodedText.empty() || rows == 1) return encodedText;
        int n = encodedText.size();
        int cols = n / rows;
        std::string res = "";

        for (int startC = 0; startC < cols; ++startC) {
            int r = 0, c = startC;
            while (r < rows && c < cols) {
                res += encodedText[r * cols + c];
                r++;
                c++;
            }
        }
        while (!res.empty() && res.back() == ' ') {
            res.pop_back();
        }
        return res;
    }
};

class Solution {
    public String decodeCiphertext(String encodedText, int rows) {
        if (encodedText.isEmpty() || rows == 1) return encodedText;
        int n = encodedText.length();
        int cols = n / rows;
        StringBuilder sb = new StringBuilder();

        for (int startC = 0; startC < cols; startC++) {
            int r = 0, c = startC;
            while (r < rows && c < cols) {
                sb.append(encodedText.charAt(r * cols + c));
                r++;
                c++;
            }
        }
        int len = sb.length();
        while (len > 0 && sb.charAt(len - 1) == ' ') {
            len--;
        }
        return sb.substring(0, len);
    }
}

/**
 * @param {string} encodedText
 * @param {number} rows
 * @return {string}
 */
var decodeCiphertext = function(encodedText, rows) {
    if (!encodedText || rows === 1) return encodedText;
    const n = encodedText.length;
    const cols = Math.floor(n / rows);
    const res = [];

    for (let startC = 0; startC < cols; startC++) {
        let r = 0, c = startC;
        while (r < rows && c < cols) {
            res.push(encodedText[r * cols + c]);
            r++;
            c++;
        }
    }
    return res.join('').trimEnd();
};
